const rtdal007987Source0002 = `rshift.splitppp <- function(X, ..., which=seq_along(X),
                            nsim=1, drop=TRUE)
{
  verifyclass(X, "splitppp")
  check.1.integer(nsim)
  
  if("group" %in% names(list(...)))
    stop(paste("argument", sQuote("group"),
               "not implemented for splitppp objects"))

  if(is.null(which)) {
    iwhich <- which <- seq_along(X)
  } else {
    id <- seq_along(X)
    names(id) <- names(X)
    iwhich <- id[which]
    if(length(iwhich) == 0)
      stop(paste("Argument", sQuote("which"), "did not match any marks"))
  }
  
  # validate arguments and determine common clipping window
  arglist <- handle.rshift.args(X[[1]]$window, ..., edgedefault="torus")

  if(!is.null(clip <- arglist$clip)) {
    # clip the patterns that are not to be shifted
    if(length(iwhich) < length(X)) 
      X[-iwhich] <- lapply(X[-iwhich], "[.ppp", i=clip)
  }
  Xvariable <- X[iwhich]

  resultlist <- vector(mode="list", length=nsim)

  for(isim in seq_len(nsim)) {
    Xsim <- X
    ## perform shift on selected patterns
    ## (setting group = NULL ensures each pattern is not split further)
    shiftXsub <- do.call(lapply, append(list(Xvariable, rshift.ppp, group=NULL),
                                        arglist))
    ## put back
    Xsim[iwhich] <- shiftXsub
    resultlist[[isim]] <- Xsim
  }

  return(simulationresult(resultlist, nsim, drop))
}`

const rtdal007987Source0003 = "rshift.ppp <- function(X, ..., which=NULL, group, nsim=1, drop=TRUE)\n{\n  verifyclass(X, \"ppp\")\n  check.1.integer(nsim)\n  \n  # validate arguments and determine common clipping window\n  arglist <- handle.rshift.args(X$window, ..., edgedefault=\"torus\")\n\n  # default grouping\n  #   (NULL is not the default)\n  #   (NULL means all points shifted in parallel)\n  if(missing(group))\n    group <- if(is.multitype(X)) marks(X) else NULL\n\n  # if no grouping, use of `which' is undefined\n  if(is.null(group) && !is.null(which))\n    stop(paste(\"Cannot apply argument\", sQuote(\"which\"),\n               \"; no grouping defined\"))\n\n  resultlist <- vector(mode=\"list\", length=nsim)\n  \n  # if grouping, use split\n  if(!is.null(group)) {\n    Y <- split(X, group)\n    splitshifts <- do.call(rshift.splitppp,\n                           append(list(Y, which=which, nsim=nsim, drop=FALSE),\n                                  arglist))\n    for(isim in seq_len(nsim)) {\n      Xsim <- X\n      split(Xsim, group) <- splitshifts[[isim]]\n      resultlist[[isim]] <- Xsim\n    }\n    return(simulationresult(resultlist, nsim, drop))\n  } \n    \n  # ungrouped point pattern\n  # shift all points in parallel\n\n  # recover arguments\n  radius <- arglist$radius\n  width  <- arglist$width\n  height <- arglist$height\n  edge   <- arglist$edge\n  clip   <- arglist$clip\n \n  W <- rescue.rectangle(Window(X))\n\n  if(edge == \"torus\") {\n    if(!is.rectangle(W))\n      stop(\"edge = 'torus' is only meaningful for rectangular windows\")\n    xr <- W$xrange\n    yr <- W$yrange\n    Wide <- diff(xr)\n    High <- diff(yr)\n  }\n\n  ## .......... simulation loop ..................\n  resultlist <- vector(mode=\"list\", length=nsim)\n  for(isim in seq_len(nsim)) {\n    #' generate random translation vector\n    if(!is.null(radius)) {\n      jump <- runifdisc(1, radius=radius)\n    } else {\n      jump <- list(x=runif(1, min=0, max=width),\n                   y=runif(1, min=0, max=height))\n    }\n    #' translate points of X\n    x <- X$x + jump$x\n    y <- X$y + jump$y\n    #' wrap points\n    if(edge == \"torus\") {\n      x <- xr[1] + (x - xr[1]) %% Wide\n      y <- yr[1] + (y - yr[1]) %% High\n    }\n    #' save as point pattern\n    Xsim <- X\n    Xsim$x <- x\n    Xsim$y <- y\n    #' clip to window\n    if(!is.null(clip))\n      Xsim <- Xsim[clip]\n    #' save result\n    resultlist[[isim]] <- Xsim\n  }\n  ## ................ end loop ..................\n  return(simulationresult(resultlist, nsim, drop))\n}"

const rtdal007987Source0004 = `handle.rshift.args <- function(W, ...,
                               radius=NULL, width=NULL, height=NULL,
                               edge=NULL, clip=NULL, edgedefault)
{
  verifyclass(W, "owin")
  W <- rescue.rectangle(W)
  
  if(length(aargh <- list(...)) > 0)
    stop(paste("Unrecognised arguments:",
               paste(names(aargh), collapse=",")))
  
  if(!is.null(radius)) {
    # radial generator
    if(!(is.null(width) && is.null(height)))
    stop(paste(sQuote("radius"), "is incompatible with",
               sQuote("width"), "and", sQuote("height")))
  } else {
    # rectangular generator
    if(is.null(width) != is.null(height))
      stop("Must specify both width and height, if one is specified")
    if(is.null(width)) width <- diff(W$xrange)
    if(is.null(height)) height <- diff(W$yrange)
  }
  
  if(is.null(edge))
    edge <- edgedefault
  else if(!(edge %in% c("torus", "erode", "none")))
    stop(paste("Unrecognised option erode=", sQuote(edge)))

  # determine whether clipping window is needed
  if(is.null(clip))
    clip <- switch(edge,
                   torus= NULL,
                   none= W,
                   erode={
                     if(!is.null(radius))
                       erosion.owin(W, radius)
                     else if(W$type == "rectangle")
                       trim.rectangle(W, width, height)
                     else
                       erosion.owin(W, max(width, height))
                   })

  return(list(radius=radius, width=width, height=height,
              edge=edge, clip=clip))
}`

