const rtdal008017Source0004 = `dkernel <- function(x,  kernel="gaussian", mean=0, sd=1) {
  kernel <- match.kernel(kernel)
  stopifnot(is.numeric(x))
  stopifnot(is.numeric(sd) && length(sd) == 1 && sd > 0)
  a <- sd * kernel.factor(kernel)
  y <- abs(x-mean)/a
  dens <-
    switch(kernel,
           gaussian       = { dnorm(y) },
           rectangular    = { ifelse(y < 1, 1/2, 0) },
           triangular     = { ifelse(y < 1, (1 - y), 0) },
           epanechnikov   = { ifelse(y < 1, (3/4) * (1 - y^2), 0) },
           biweight       = { ifelse(y < 1, (15/16) * (1 - y^2)^2, 0) },
           cosine         = { ifelse(y < 1, (1 + cos(pi * y))/2, 0) },
           optcosine      = { ifelse(y < 1, (pi/4) * cos(pi * y/2), 0) }
           )
  dens/a
}`

const rtdal008017Source0005 = `pkernel <- function(q, kernel="gaussian", mean=0, sd=1, lower.tail=TRUE){
  kernel <- match.kernel(kernel)
  stopifnot(is.numeric(q))
  stopifnot(is.numeric(sd) && length(sd) == 1 && sd > 0)
  a <- sd * kernel.factor(kernel)
  y <- (q-mean)/a
  switch(kernel,
         gaussian = {
           pnorm(y, lower.tail=lower.tail)
         },
         rectangular = {
           punif(y, min=-1, max=1, lower.tail=lower.tail)
         },
         triangular = {
           p <- ifelse(y < -1, 0, ifelse(y > 1, 1,
                       ifelse(y < 0, y + y^2/2 + 1/2,
                              y - y^2/2 + 1/2)))
           if(lower.tail) p else (1 - p)
         },
         epanechnikov = {
           p <- ifelse(y < -1, 0, ifelse(y > 1, 1,
                        (2 + 3 * y - y^3)/4))
           if(lower.tail) p else (1 - p)
         },
         biweight = {
           p <- ifelse(y < -1, 0, ifelse(y > 1, 1,
                       (15 * y - 10 * y^3 + 3 * y^5 + 8)/16))
           if(lower.tail) p else (1 - p)
         },
         cosine = {
           p <- ifelse(y < -1, 0, ifelse(y > 1, 1,
                       (y + sin(pi * y)/pi + 1)/2))
           if(lower.tail) p else (1 - p)
         },
         optcosine = {
           p <- ifelse(y < -1, 0, ifelse(y > 1, 1,
                       (sin(pi * y/2) + 1)/2))
           if(lower.tail) p else (1 - p)
         })
}`

const rtdal008017Source0006 = "qkernel <- function(p, kernel=\"gaussian\", mean=0, sd=1, lower.tail=TRUE) {\n  kernel <- match.kernel(kernel)\n  stopifnot(is.numeric(p))\n  stopifnot(is.numeric(sd) && length(sd) == 1 && sd > 0)\n  a <- sd * kernel.factor(kernel)\n  if(!lower.tail)\n    p <- 1 - p\n  y <-\n    switch(kernel,\n           gaussian = {\n             qnorm(p, lower.tail=lower.tail)\n           },\n           rectangular = {\n             qunif(p, min=-1, max=1, lower.tail=lower.tail)\n           },\n           triangular = {\n             ifelse(p < 1/2, sqrt(2 * p) - 1, 1 - sqrt(2 * (1-p)))\n           },\n           epanechnikov = {\n             # solve using `polyroot'\n             yy <- numeric(n <- length(p))\n             yy[p == 0] <- -1\n             yy[p == 1] <-  1\n             inside <- (p != 0) & (p != 1)\n             # coefficients of polynomial (2 + 3 y - y^3)/4\n             z <- c(2, 3, 0, -1)/4\n             for(i in seq(n)[inside]) {\n               sol <- polyroot(z - c(p[i], 0, 0, 0))\n               ok <- abs(Im(sol)) < 1e-6\n               realpart <- Re(sol)\n               ok <- ok & (abs(realpart) <= 1)\n               if(sum(ok) != 1)\n                 stop(paste(\"Internal error:\", sum(ok), \"roots of polynomial\"))\n               yy[i] <- realpart[ok]\n             }\n             yy\n           },\n           biweight = {\n             # solve using `polyroot'\n             yy <- numeric(n <- length(p))\n             yy[p == 0] <- -1\n             yy[p == 1] <-  1\n             inside <- (p != 0) & (p != 1)\n             # coefficients of polynomial (8 + 15 * y - 10 * y^3 + 3 * y^5)/16\n             z <- c(8, 15, 0, -10, 0, 3)/16\n             for(i in seq(n)[inside]) {\n               sol <- polyroot(z - c(p[i], 0, 0, 0, 0, 0))\n               ok <- abs(Im(sol)) < 1e-6\n               realpart <- Re(sol)\n               ok <- ok & (abs(realpart) <= 1)\n               if(sum(ok) != 1) \n                 stop(paste(\"Internal error:\", sum(ok), \"roots of polynomial\"))\n               yy[i] <- realpart[ok]\n             }\n             yy\n           },\n           cosine = {\n             # solve using `uniroot'\n             g <- function(y, pval) { (y + sin(pi * y)/pi + 1)/2 - pval }\n             yy <- numeric(n <- length(p))\n             yy[p == 0] <- -1\n             yy[p == 1] <-  1\n             inside <- (p != 0) & (p != 1)\n             for(i in seq(n)[inside]) \n               yy[i] <- uniroot(g, c(-1,1), pval=p[i])$root\n             yy\n           },\n           optcosine = {\n             (2/pi) * asin(2 * p - 1)\n           })\n  return(mean + a * y)\n}"

const rtdal008017Source0007 = `kernel.moment <- local({

  kernel.moment <- function(m, r, kernel="gaussian",
                            mean=0, sd=1/kernel.factor(kernel)) {
    ker <- match.kernel(kernel)
    check.1.integer(m)
    needs.rescaling <- !missing(mean) || !missing(sd)
    halfwidth <- if(missing(sd)) 1 else (sd * kernel.factor(ker))
    #' restrict to support
    if(ker != "gaussian") {
      r <- pmin(r, mean+halfwidth)
      r <- pmax(r, mean-halfwidth)
    }
    if(!(m %in% c(0,1,2))) {
      ## use generic integration
      neginf <- mean - if(ker == "gaussian") (10 * sd) else halfwidth
      result <- numeric(length(r))
      for(i in seq_along(r))
        result[i] <- integralvalue(kintegrand,
                                   lower=neginf, upper=r[i],
                                   m=m, ker=ker, mean=mean, sd=sd)
      return(result)
    }
    if(needs.rescaling) {
      ## convert to standard form and use analytic results
      y <- (r - mean)/halfwidth
      if(m == 0)
        return(kernel.moment(0, y, kernel=ker))
      else if(m == 1)
        return(mean * kernel.moment(0, y, kernel=ker)
               + halfwidth * kernel.moment(1, y, kernel=ker))
      else
        return(mean^2 * kernel.moment(0, y, kernel=ker)
               + 2 * mean * halfwidth * kernel.moment(1, y, kernel=ker)
               + halfwidth^2 * kernel.moment(2, y, kernel=ker))
    }
    ## kernel is now in standard form with support [-1, 1] unless Gaussian
    switch(ker,
           gaussian={
             if(m == 0) return(pnorm(r)) else
             if(m == 1) return(-dnorm(r)) else
             return(ifelse(r == -Inf, 0,
                    ifelse(r == Inf, 1,
                           pnorm(r) - r * dnorm(r))))
           },
           rectangular = {
             if(m == 0) return((r + 1)/2) else
             if(m == 1) return((r^2 - 1)/4) else
             return((r^3 + 1)/6)
           },
           triangular={
             m1 <- m+1
             m2 <- m+2
             const <- ((-1)^m1)/m1 + ((-1)^m2)/m2
             answer <- (r^m1)/m1 + ifelse(r < 0, 1, -1) * (r^m2)/m2 - const
             return(answer)
           },
           epanechnikov = {
             if(m == 0)
               return((2 + 3*r - r^3)/4)
             else if(m == 1)
               return((-3 + 6*r^2 - 3*r^4)/16)
             else
               return(( 2 + 5*r^3  - 3* r^5)/20)
           },
           biweight = {
             if(m == 0)
               return((3*r^5 - 10*r^3 + 15*r + 8)/16)
             else if(m == 1)
               return((5*r^6 - 15*r^4 + 15*r^2 -5)/32)
             else 
               return((15*r^7 - 42*r^5 + 35*r^3 + 8)/112)
           },
           cosine={
             pr <- pi * r
             if(m == 0)
               return((r + sin(pr)/pi + 1)/2)
             else if(m == 1)
               return((r^2-1)/4 + (pr*sin(pr) + cos(pr) + 1)/(2*pi^2))
             else
               return((r^3 + 1)/6 +
                      ((pr^2-2) * sin(pr) + 2*pr*cos(pr) - 2*pi)/(2*pi^3))
           },
           optcosine={
             p2r <- (pi/2) * r
             if(m == 0)
               return((sin(p2r) + 1)/2)
             else if(m == 1)
               return((p2r * sin(p2r) + cos(p2r) - pi/2)/pi)
             else
               return((2/pi^2) *
                      ((p2r^2-2)*sin(p2r) + 2*p2r*cos(p2r) + (pi/2)^2-2))
           }
           )
  }

  integralvalue <- function(...) integrate(...)$value
  
  kintegrand <- function(x, m, ker, mean, sd) {
    (x^m) * dkernel(x=x, kernel=ker, mean=mean, sd=sd)
  }

  kernel.moment
})`

