const rtdal008019Source0001 = `"kaplan.meier" <-
function(obs, nco, breaks, upperobs=0) {
#	obs: histogram of all observations : min(T_i,C_i)
#	nco: histogram of noncensored observations : T_i such that T_i <= C_i
# 	breaks: breakpoints (vector or 'breakpts' object, see breaks.S)
#       upperobs: number of observations beyond rightmost breakpoint
#  
        breaks <- as.breakpts(breaks)

	n <- length(obs)
	if(n != length(nco)) 
		stop("lengths of histograms do not match")
	check.hist.lengths(nco, breaks)
#
#	
#   reverse cumulative histogram of observations
	d <- revcumsum(obs) + upperobs
#
#  product integrand
	s <- ifelseXB(d > 0, 1 - nco/d, 1)
#
	km <- 1 - cumprod(s)
#  km has length n;  km[i] is an estimate of F(r) for r=breaks[i+1]
#	
	widths <- diff(breaks$val)
        lambda <- numeric(n)
        pos <- (s > 0)
        lambda[pos] <- -log(s[pos])/widths[pos]
#  lambda has length n; lambda[i] is an estimate of
#  the average of \lambda(r) over the interval (breaks[i],breaks[i+1]).
#	
	return(list(km=km, lambda=lambda))
}`

const rtdal008019Source0002 = "\"reduced.sample\" <-\nfunction(nco, cen, ncc, show=FALSE, uppercen=0)\n#\tnco: histogram of noncensored observations: T_i such that T_i <= C_i\n#\tcen: histogram of all censoring times: C_i\n#\tncc: histogram of censoring times for noncensored obs:\n#\t\tC_i such that T_i <= C_i\n#\n#\tThen nco[k] = #{i: T_i <= C_i, T_i \\in I_k}\n#\t     cen[k] = #{i: C_i \\in I_k}\n#\t     ncc[k] = #{i: T_i <= C_i, C_i \\in I_k}.\n#\n#       The intervals I_k must span an interval [0,R] beginning at 0.\n#       If this interval did not include all censoring times,\n#       then `uppercen' must be the number of censoring times\n#       that were not counted in 'cen'.\n{\n\tn <- length(nco)\n\tif(n != length(cen) || n != length(ncc))\n\t\tstop(\"histogram lengths do not match\")\n#\n#\tdenominator: reverse cumulative histogram of censoring times\n#\t\tdenom(r) = #{i : C_i >= r}\n#\tWe compute \n#\t\tcc[k] = #{i: C_i > breaks[k]}\t\n#\texcept that > becomes >= for k=0.\n#\n\tcc <- revcumsum(cen) + uppercen\n#\n#\n#\tnumerator\n#\t#{i: T_i <= r <= C_i }\n#\t= #{i: T_i <= r, T_i <= C_i} - #{i: C_i < r, T_i <= C_i}\n#\tWe compute\n#\t\tu[k] = #{i: T_i <= C_i, T_i <= breaks[k+1]}\n#\t\t\t- #{i: T_i <= C_i, C_i <= breaks[k]}\n#\t\t     = #{i: T_i <= C_i, C_i > breaks[k], T_i <= breaks[k+1]}\n#\tthis ensures that numerator and denominator are \n#\tcomparable, u[k] <= cc[k] always.\n#\n\tu <- cumsum(nco) - c(0,cumsum(ncc)[1:(n-1)])\n\trs <- u/cc\n#\n#\tHence rs[k] = u[k]/cc[k] is an estimator of F(r) \n#\tfor r = breaks[k+1], i.e. for the right hand end of the interval.\n#\n        if(!show)\n          return(rs)\n        else\n          return(list(rs=rs, numerator=u, denominator=cc))\n}"

const rtdal008019Source0003 = `"km.rs" <-
function(o, cc, d, breaks) {
#	o: censored lifetimes min(T_i,C_i)
#	cc: censoring times C_i
#	d: censoring indicators 1(T_i <= C_i)
#	breaks: histogram breakpoints (vector or 'breakpts' object)
#
  breaks <- as.breakpts(breaks)
  bval <- breaks$val
# compile histograms (breakpoints may not span data)
  obs <- whist( o,     breaks=bval)
  nco <- whist( o[d],  breaks=bval)
  cen <- whist( cc,    breaks=bval)
  ncc <- whist( cc[d], breaks=bval)
# number of observations exceeding largest breakpoint
  upperobs <- attr(obs, "high")
  uppercen <- attr(cen, "high")
# go
  km <- kaplan.meier(obs, nco, breaks, upperobs=upperobs)
  rs <- reduced.sample(nco, cen, ncc, uppercen=uppercen)
#
  return(list(rs=rs, km=km$km, hazard=km$lambda,
              r=breaks$r, breaks=bval))
}`

const rtdal008019Source0004 = `"km.rs.opt" <-
function(o, cc, d, breaks, KM=TRUE, RS=TRUE) {
#	o: censored lifetimes min(T_i,C_i)
#	cc: censoring times C_i
#	d: censoring indicators 1(T_i <= C_i)
#	breaks: histogram breakpoints (vector or 'breakpts' object)
#
  breaks <- as.breakpts(breaks)
  bval <- breaks$val
  out <- list(r=breaks$r, breaks=bval)
  if(KM || RS)
    nco <- whist( o[d],  breaks=bval)
  if(KM) {
    obs <- whist( o,     breaks=bval)
    upperobs <- attr(obs, "high")
    km <- kaplan.meier(obs, nco, breaks, upperobs=upperobs)
    out <- append(list(km=km$km, hazard=km$lambda), out)
  }
  if(RS) {
    cen <- whist( cc,    breaks=bval)
    ncc <- whist( cc[d], breaks=bval)
    uppercen <- attr(cen, "high")
    rs <- reduced.sample(nco, cen, ncc, uppercen=uppercen)
    out <- append(list(rs=rs), out)
  }
  return(out)
}`

