const rtdal008023Source0001 = `stieltjes <- function(f, M, ...) {
  ## stieltjes integral of f(x) dM(x)
  stopifnot(is.function(f))
  StieltjesCalc(M, f, ...)
}`

const rtdal008023Source0002 = `StieltjesCalc <- function(M, f, ...) {
  UseMethod("StieltjesCalc")
}`

const rtdal008023Source0003 = `StieltjesCalc.stepfun <- function(M, f, ...) {
  stopifnot(inherits(M, "stepfun"))
  envM <- environment(M)
  #' jump locations
  x <- get("x", envir=envM)
  #' values of integrand
  fx <- f(x, ...)
  #' jump amounts
  xx <- c(-Inf, (x[-1L] + x[-length(x)])/2, Inf)
  dM <- diff(M(xx))
  #' integrate f(x) dM(x)
  f.dM <- fx * dM
  result <- sum(f.dM[is.finite(f.dM)])
  return(list(result))
}`

