const rtdal008024Source0001 = `transformquantiles <- function(X, uniform=FALSE, reverse=FALSE, ...) {
  if(!uniform && !reverse) return(X)
  o <- order(X[])
  V <- X
  n <- length(o)
  if(uniform) V[][o] <- (seq_len(n) - 0.5)/n
  if(reverse) V[][o] <- V[][rev(o)]
  return(V)
}`

