const rtdal008030Source0003 = `distppll <- function(p, l, mintype=0,
                     method=c("C", "Fortran", "interpreted"), listit=FALSE) {
  np <- nrow(p)
  nl <- nrow(l)
  xp <- p[,1]
  yp <- p[,2]
  if(is.na(match(mintype,0:2)))
    stop(paste("Argument", sQuote("mintype"), "must be 0, 1 or 2.\n"))
  method <- match.arg(method)
  if(method == "Fortran") {
    warning("method='Fortran' is no longer supported; method='C' was used")
    method <- "C"
  }
  switch(method,
         interpreted={
           dx <- l[,3]-l[,1]
           dy <- l[,4]-l[,2]
           #' segment lengths
           leng <- sqrt(dx^2 + dy^2)
           #' rotation sines & cosines
           co <- dx/leng
           si <- dy/leng
           co <- matrix(co, nrow=np, ncol=nl, byrow=TRUE)
           si <- matrix(si, nrow=np, ncol=nl, byrow=TRUE)
           #' matrix of squared distances from p[i] to 1st endpoint of segment j
           xp.x1 <- outer(xp, l[,1], "-")
           yp.y1 <- outer(yp, l[,2], "-")
           d1 <- xp.x1^2 + yp.y1^2
           #' ditto for 2nd endpoint
           xp.x2 <- outer(xp, l[,3], "-")
           yp.y2 <- outer(yp, l[,4], "-")
           d2 <- xp.x2^2 + yp.y2^2
           #' for each (i,j) rotate p[i] around 1st endpoint of segment j
           #' so that line segment coincides with x axis
           xpr <- xp.x1 * co + yp.y1 * si
           ypr <-  - xp.x1 * si + yp.y1 * co
           d3 <- ypr^2
           #' test
           lenf <- matrix(leng, nrow=np, ncol=nl, byrow=TRUE)
           zero <- (lenf < .Machine$double.eps) 
           outside <- (zero | xpr < 0 | xpr > lenf) 
           if(any(outside))
             d3[outside] <- Inf

           dsq <- matrix(pmin.int(d1, d2, d3),nrow=np, ncol=nl)
           d <- sqrt(dsq)
           if(mintype >= 1)
             min.d <- apply(d, 1, min)
           if(mintype == 2)
             min.which <- apply(d, 1, which.min)
         },
         C = {
           eps <- .Machine$double.eps
           temp <- .C(C_prdist2segs,
                      x=as.double(xp),
                      y=as.double(yp),
                      npoints =as.integer(np),
                      x0=as.double(l[,1]),
                      y0=as.double(l[,2]),
                      x1=as.double(l[,3]),
                      y1=as.double(l[,4]),
                      nsegments=as.integer(nl),
                      epsilon=as.double(eps),
                      dist2=as.double(numeric(np * nl)))
           d <- matrix(sqrt(temp$dist2), nrow=np, ncol=nl)
           if(mintype == 1) {
             min.d <- apply(d, 1, min)
           } else if(mintype == 2) {
             min.which <- apply(d, 1, which.min)
             min.d <- d[cbind(1:np, min.which)]
           }
         })
  ###### end switch #####
  if(mintype==0)
    return(if(listit) list(d=d) else d)
  else if(mintype==1)
    return(list(d=d, min.d=min.d))
  else if(mintype==2) 
    return(list(d=d, min.d=min.d, min.which=min.which))
}`

const rtdal008030Source0005 = `NNdist2segments <- function(xp, yp, x0, y0, x1, y1, bigvalue,
                            wantindex=TRUE, wantproj=FALSE) {
  ## find distance from each point to nearest segment
  ## If 'wantindex' then also return index of segment  
  ## If 'wantproj' then also return (x,y) and (tp) coordinates of projection
  np <- length(xp)
  ns <- length(x0)
  dist2 <- rep(bigvalue, np)
  if(wantproj) {
    z <- .C(C_nnproj2segs,
            xp=as.double(xp),
            yp=as.double(yp),
            npoints=as.integer(np),
            x0=as.double(x0),
            y0=as.double(y0),
            x1=as.double(x1),
            y1=as.double(y1),
            nsegments=as.integer(ns),
            epsilon=as.double(.Machine$double.eps),
            dist2=as.double(dist2),
            index=as.integer(integer(np)),
            xproj=as.double(numeric(np)),
            yproj=as.double(numeric(np)),
            tproj=as.double(numeric(np)))
    return(list(dist2 = z$dist2,
                index = z$index + 1L,
                xproj = z$xproj,
                yproj = z$yproj,
                tproj = z$tproj))
  } else if(wantindex) {
    z <- .C(C_nndist2segs,
            xp=as.double(xp),
            yp=as.double(yp),
            npoints=as.integer(np),
            x0=as.double(x0),
            y0=as.double(y0),
            x1=as.double(x1),
            y1=as.double(y1),
            nsegments=as.integer(ns),
            epsilon=as.double(.Machine$double.eps),
            dist2=as.double(dist2),
            index=as.integer(integer(np)))
    return(list(dist2=z$dist2,
                index=z$index + 1L))
  } else {
    z <- .C(C_nnd2segs,
            xp=as.double(xp),
            yp=as.double(yp),
            npoints=as.integer(np),
            x0=as.double(x0),
            y0=as.double(y0),
            x1=as.double(x1),
            y1=as.double(y1),
            nsegments=as.integer(ns),
            epsilon=as.double(.Machine$double.eps),
            dist2=as.double(dist2))
    return(list(dist2=z$dist2))
  }
}`

