const rtdal008176Source0001 = `read.gwt2nb <- function(file, region.id=NULL) {
  con <- file(file, open="r")   #opens the file
  firstline <- unlist(strsplit(readLines(con,1)," "))
  if (length(firstline) == 4L) {
    n <- as.integer(firstline[2])
    shpfile <- firstline[3]
    ind <- firstline[4]
    if (ind != deparse(substitute(region.id)))
      warning(paste("region.id not named", ind))
  } else if (length(firstline) == 1L) {
    n <- as.integer(firstline[1])
    shpfile <- as.character(NA)
    ind <- as.character(NA)
    warning("Old-style GWT file")
  } else stop("Invalid header line format for GWT file")
  close(con)
  if (n < 1) stop("non-positive number of entities")
  nseq <- 1:n
  if (is.null(region.id)) region.id <- nseq
  if (n != length(region.id))
    stop("Mismatch in dimensions of GWT file and region.id")
  if (length(unique(region.id)) != length(region.id))
      stop("non-unique region.id given")
  odij <- read.table(file, skip=1)
      # convert region.id to order
  regodij <- match(odij[,1], region.id)
# 7 anmolter 2018-01-26
        stopifnot(!anyNA(regodij))
  regddij <- match(odij[,2], region.id)
        stopifnot(!anyNA(regddij))
  odij <- cbind(regodij, regddij, odij[,3])
  qorder <- order(odij[,1],odij[,2])
  odij <- odij[qorder,]
  origvec <- unique(odij[,1])
  if (!all(nseq %in% origvec))
    warning(paste(paste(region.id[which(!(nseq %in% origvec))], 
      collapse=", "), "are not origins"))
  destvec <- unique(odij[,2])
  if (!all(nseq %in% destvec))
    warning(paste(paste(region.id[which(!(nseq %in% destvec))], 
      collapse=", "), "are not destinations"))

  res <- vector(mode="list", length=n)
  vlist <- vector(mode="list", length=n)
  rle.sn <- rle(odij[,1])
  cs1.sn <- cumsum(rle.sn$lengths)
  cs0.sn <- c(1, cs1.sn[1:(n-1)]+1)
  ii <- 1
  for (i in 1:n) {
# Bug hit by Thomas Halvorsen 10/2006, was already fixed in sn2listw()
    if (!is.na(rle.sn$value[ii]) && rle.sn$value[ii] == i) {
      res[[i]] <- as.integer(odij[cs0.sn[ii]:cs1.sn[ii],2])
      vlist[[i]] <- as.double(odij[cs0.sn[ii]:cs1.sn[ii],3])
      ii <- ii+1
    } else {
      res[[i]] <- 0L
    }
  }

  class(res) <- c("nb", "GWT")
  attr(res, "region.id") <- region.id
  attr(res, "neighbours.attrs") <- as.character(NA)
  attr(res, "weights.attrs") <- as.character(NA)
  attr(res, "GeoDa") <- list(dist=vlist, shpfile=shpfile, ind=ind)
  attr(res, "call") <- match.call()
  attr(res, "n") <- n
  res <- sym.attr.nb(res)
        NE <- length(res) + sum(card(res))
        if (get.SubgraphOption() && get.SubgraphCeiling() > NE) {
          ncomp <- n.comp.nb(res)
          attr(res, "ncomp") <- ncomp
          if (ncomp$nc > 1) warning("neighbour object has ", ncomp$nc, " sub-graphs")
        }
  res
}`

const rtdal008176Source0004 = `read.dat2listw <- function(file) {
  wmat <- read.table(file)
        stopifnot(ncol(wmat) == 3)
        stopifnot(is.numeric(wmat[,3]))
        if (storage.mode(wmat[,1]) != "integer")
            storage.mode(wmat[,1])<- "integer"
        if (storage.mode(wmat[,2]) != "integer")
            storage.mode(wmat[,2]) <- "integer"
  sn <- wmat[order(wmat[,1]),]
  IDS <- unique(sn[,1])
  class(sn) <- c("spatial.neighbour", "data.frame")
  attr(sn, "n") <- length(IDS)
  attr(sn, "region.id") <- as.character(IDS)
  listw <- sn2listw(sn)
  listw
}`

const rtdal008176Source0006 = `write.sn2DBF <- function(sn, file) {
  if(!inherits(sn, "spatial.neighbour")) 
      stop("not a spatial.neighbour object")
  n <- attr(sn, "n")
  if (n < 1) stop("non-positive number of entities")
  nms <- as.character(attr(sn, "region.id"))
  sn[,1] <- as.integer(nms[sn[,1]])
  sn[,2] <- as.integer(nms[sn[,2]])
  names(sn)[1:2] <- c("ID", "NID")
  sn <- cbind(data.frame(Field1=rep(0L, nrow(sn))), sn)
  if (requireNamespace("foreign", quietly=TRUE)) {
    foreign::write.dbf(sn, file)
  } else warning("foreign::read.dbf not available")
  invisible(sn)
}`

const rtdal008176Source0007 = `nb2INLA <-function(file, nb)
{
        
        n<-length(nb)

        if(!file.create(file))
        {
                stop("Cannot open file")
        }

        txt<-paste(n, "\n", sep="")
        cat(txt, file=file, append = TRUE)
        crd <- card(nb)

        for(i in 1:length(nb))
        {
                if (crd[i] == 0) txt <- paste(c(i, 0), collapse=" ")
# Marcos Prates 2011-10-07 no-neighbour case
                else txt<-paste(c(i, length(nb[[i]]), nb[[i]]), collapse=" ")
                txt<-paste(txt, "\n",sep="")
                cat(txt, file=file, append = TRUE)
        }
}`

const rtdal008176Source0008 = "read.swmdbf2listw <- function(fn, region.id=NULL, style=NULL, zero.policy=NULL) {\n    if (is.null(zero.policy))\n        zero.policy <- get.ZeroPolicyOption()\n    stopifnot(is.logical(zero.policy))\n    if (is.null(style)) {\n        style <- \"M\"\n    }\n  \n    if (style == \"M\")\n        warning(\"style is M (missing); style should be set to a valid value\")\n\n    res <- NULL\n\n    if (requireNamespace(\"foreign\", quietly=TRUE)) {\n        df <- try(foreign::read.dbf(fn, as.is=TRUE), silent=TRUE)\n        if (inherits(df, \"try-error\")) stop(df[1])\n        # a SWM table that is _imported_ into ArcGIS Pro does not use the\n        # leading empty `Field1`. If it is not present, add it for this\n        # function to continue as anticipated\n        dbf_names <- colnames(df)\n        nb_idx <- which(dbf_names == \"NID\")\n        # ensure that `NID` is provided\n        if (length(nb_idx) == 0) stop(\"Field `NID` not found in provided .dbf\")\n        if (nb_idx == 2L) {\n          df <- cbind(\n            Field1 = rep(0, nrow(df)),\n            df\n          )\n        }\n        if (is.null(region.id)) {\n            rn <- range(c(as.numeric(df[,2]), as.numeric(df[,3])))\n            region.id <- as.character(rn[1]:rn[2])\n            warning(\"region.id not given, c(MYID, NID) range is \",\n                paste(rn, collapse=\":\"))\n        }\n        n <- length(region.id)\n        ids <- 1:n\n        df[,2] <- match(df[, 2], region.id)\n        if (anyNA(df[,2])) warning(\"NAs in MYID matching\")\n        df[,3] <- match(df[, 3], region.id)\n        if (anyNA(df[,3])) warning(\"NAs in NID matching\")\n        if (!all(df[,2] %in% ids) || !all(df[,3] %in% ids))\n            warning(\"some IDs missing\")\n        df1 <- df[order(df[,2], df[,3]), -1]\n        attr(df1, \"n\") <- n\n        class(df1) <- c(class(df1), \"spatial.neighbour\")\n        attr(df1, \"region.id\") <- region.id\n        res0 <- try(sn2listw(df1, style=style, zero.policy=zero.policy),\n            silent=TRUE)\n        if (inherits(res0, \"try-error\")) stop(res0[1])\n        else res <- res0\n    } else warning(\"foreign::read.dbf not available\")\n\n    if (!inherits(res, \"listw\")) warning(\"creation of listw object from SWM DBF file failed\")\n    res\n}"

const rtdal008176Source0010 = "write.swmdbf <- function(listw, file, ind, region.id = attr(listw, \"region.id\")) {\n  stopifnot(\n    \"`ind` must be a character scalar\" = is.character(ind),\n    \"`ind` must be a character scalar\" = length(ind) == 1,\n    \"`listw` must be a `listw` spatial weights matrix\" = inherits(listw, \"listw\"),\n    \"package foreign is required to write to dbf\" = requireNamespace(\"foreign\")\n  )\n\n  n <- length(listw$neighbours)\n\n  # Unsure if it is possible to not have region.id in current state \n  # of spdep, including in the event.\n  if (is.null(region.id)) {\n    warning(\"`region.id` not supplied. Using row positions.\")\n    region.id <- as.character(1:n)\n  }\n\n  # create indices from indices to match length of neighbors\n  from <- region.id[rep.int(1:n, card(listw$neighbours))]\n  # flatten the neighbor ids\n  to <- region.id[unlist(listw$neighbours)]\n  # flatten the weights\n  weight <- unlist(listw$weights)\n  # construct a data frame from the flattened structure\n  # note that the columns _must_ be integers for the ArcGIS Pro tool to work\n  # RSB 241124\n  smf <- storage.mode(from)\n  if (smf != \"integer\") {\n    if (smf == \"character\") {\n      from <- as.integer(from)\n      if (anyNA(from)) stop(\"from character indices could not be coerced to integer\")\n    } else if (smf == \"double\") {\n      ofrom <- as.integer(round(from))\n      from <- as.integer(from)\n      if (any(from != ofrom)) stop(\"from double indices could not be coerced to integer\")\n    } else stop(\"from indices invalid: \", smf)\n  }\n  smt <- storage.mode(to)\n  if (smt != \"integer\") {\n    if (smt == \"character\") {\n      to <- as.integer(to)\n      if (anyNA(to)) stop(\"to character indices could not be coerced to integer\")\n    } else if (smt == \"double\") {\n      oto <- as.integer(round(to))\n      to <- as.integer(to)\n      if (any(to != oto)) stop(\"to double indices could not be coerced to integer\")\n    } else stop(\"to indices invalid: \", smt)\n  }\n  \n  res <- data.frame(from, to, weight)\n\n  # give appropriate column names. The first column must be \n  # the unique ID column\n  names(res) <- c(ind, \"NID\", \"WEIGHT\")\n  foreign::write.dbf(res, file)\n  invisible(res)\n}"

